package dev.algorithmlearning.api.courses.data;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="course_lessons") class CourseLessonEntity { @Id UUID id; @ManyToOne(optional=false) @JoinColumn(name="category_id") CourseCategoryEntity category; @Column(name="source_identity") String sourceIdentity; @Column(name="source_markdown_path") String sourceMarkdownPath; @Column(name="english_title") String englishTitle; String tags,detail; @Column(name="source_url") String sourceUrl; @Column(name="source_type") String sourceType; @Column(name="sort_order") int sortOrder; @Column(name="created_at") Instant createdAt; @Column(name="updated_at") Instant updatedAt; protected CourseLessonEntity(){} CourseLessonEntity(UUID id,CourseCategoryEntity category,String sourceIdentity,String sourceMarkdownPath,String englishTitle,String tags,String detail,String sourceUrl,String sourceType,int sortOrder,Instant createdAt,Instant updatedAt){this.id=id;this.category=category;this.sourceIdentity=sourceIdentity;this.sourceMarkdownPath=sourceMarkdownPath;this.englishTitle=englishTitle;this.tags=tags;this.detail=detail;this.sourceUrl=sourceUrl;this.sourceType=sourceType;this.sortOrder=sortOrder;this.createdAt=createdAt;this.updatedAt=updatedAt;} }
